/* MF Robot Console — vanilla JS, local assets, no third-party runtime. */
'use strict';
const $ = id => document.getElementById(id);
const icon = name => `<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const finite = v => typeof v === 'number' && Number.isFinite(v);
const fmt = (v, n=2) => finite(v) ? (Math.abs(v) < 0.00001 ? 0 : v).toFixed(n) : '—';
const CLIENT = typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : 'console-'+Date.now()+'-'+Math.random();
const LOCAL = ['127.0.0.1','localhost'].includes(location.hostname) && !new URLSearchParams(location.search).has('demo');
const stateNames = {ready:'대기 중',idle:'정지 확인',startup:'저속 출발',running:'주행 중',braking:'감속 중',reversal_wait:'전환 대기',waiting_feedback:'피드백 대기',cmd_vel_timeout:'명령 대기',fault:'정지 유지'};
let snapshot=null, manual=false, epoch=null, sequence=0, armedAt=0, armGeneration=0, armBusy=false;
let linearSetting=.10, angularSetting=.20, commandBusy=false, currentDialog='', logFilter='all', chartRange=30;
let history=[], lastHistory=0, lastHTTP=0, transport, pendingServices=new Set(), reportedResults=new Set();
const heldKeys = new Set(), heldPointers = new Map();

function toast(message, error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('toasts').append(el);setTimeout(()=>el.remove(),4500);}
function eventTime(event){return new Date(event.time*1000).toLocaleTimeString('ko-KR',{hour12:false});}
function velocity(){const directions=new Set([...heldKeys,...heldPointers.values()]);return [(Number(directions.has('forward'))-Number(directions.has('backward')))*linearSetting,(Number(directions.has('left'))-Number(directions.has('right')))*angularSetting];}

class DemoTransport {
  constructor(){this.events=[];this.results=[];this.id=0;this.owner=null;this.target=[0,0];this.output=[0,0];this.wheels=[0,0];this.position=[0,0];this.fault='';this.phase='idle';this.started=null;this.lastCommand=0;this.scene='normal';this.lastMotor=performance.now();this.waitUntil=0;this.reverse=false;this.event('데모 워크스페이스 준비 완료');this.event('가상 로봇 연결 · 수동 제어를 체험해보세요');}
  event(text,level='info'){this.events.unshift({id:++this.id,time:Date.now()/1000,text,level});this.events=this.events.slice(0,150);}
  async init(){this.timer=setInterval(()=>this.tick(),50);}
  async arm(){if(this.fault||!['normal','no_feedback'].includes(this.scene))throw Error('드라이버 상태를 먼저 복구하세요');if(this.scene!=='no_feedback'&&Math.max(...this.wheels.map(Math.abs))>.1)throw Error('바퀴가 정지한 뒤 다시 켜세요');this.owner=CLIENT;this.lastCommand=performance.now();this.waitUntil=performance.now()+200;this.event('수동 제어 시작 · 데모');return {epoch:'demo-session'};}
  async command(values){if(!this.owner)throw Error('수동 제어를 다시 켜세요');this.target=values;this.lastCommand=performance.now();return {ok:true};}
  async disarm(){if(this.owner)this.event('수동 제어 해제');this.owner=null;this.target=[0,0];this.output=[0,0];this.started=null;return {ok:true};}
  async service(name){await this.disarm();let success=true,message='';if(name==='driver_stop'){this.fault='operator_stop';message='정지 유지 요청을 처리했어요';}else if(name==='driver_reset'){if(!['normal','no_feedback'].includes(this.scene)){success=false;message='연결 및 설정에서 데모 장애를 정상으로 바꿔주세요';}else if(this.scene!=='no_feedback'&&Math.max(...this.wheels.map(Math.abs))>.1){success=false;message='바퀴가 정지한 뒤 복구하세요';}else{this.fault='';message='복구 완료 · 수동 제어를 다시 켜세요';}}else{success=false;message='데모 로봇은 리프트를 사용하지 않아요';}const id='demo-'+(++this.id);this.results.unshift({id,name,status:success?'success':'error',message});this.results=this.results.slice(0,30);this.event(message,success?'info':'error');return {job_id:id};}
  setScene(value){this.scene=value;this.owner=null;this.target=[0,0];this.output=[0,0];if(!['normal','no_feedback'].includes(value))this.fault=value==='feedback'?'motor_feedback_timeout':'serial_error: demo';this.event(value==='no_feedback'?'모터 피드백 없이 주행 · 실측값 미표시':value==='normal'?'통신 정상 복귀 · 복구 버튼을 눌러주세요':value==='feedback'?'모터 피드백 중단 체험':'시리얼 연결 끊김 체험',value==='normal'?'info':'error');}
  tick(){const now=performance.now(),dt=.05;if(this.owner&&now-this.lastCommand>350){this.owner=null;this.target=[0,0];this.event('조작 신호 만료 · 제어 해제');}
    if(this.scene==='normal')this.lastMotor=now;
    let [v,w]=this.target;if(!this.owner||this.fault||!['normal','no_feedback'].includes(this.scene))v=w=0;
    let target=[(v-w*.35)/.12,(v+w*.35)/.12];
    if(!v&&!w){this.output=[0,0];this.started=null;this.reverse=false;this.phase='idle';}
    else if(this.output.some((x,i)=>x*target[i]<-1e-6)||this.reverse){this.reverse=true;this.phase='braking';this.output=this.output.map(x=>Math.sign(x)*Math.max(0,Math.abs(x)-.2));if(this.output.every(x=>x===0)){this.phase='reversal_wait';if(this.scene==='no_feedback'||this.wheels.every(x=>Math.abs(x)<.1)){this.reverse=false;this.waitUntil=now+200;this.started=null;}}}
    else if(now<this.waitUntil){this.output=[0,0];this.phase='idle';}
    else {if(this.started===null)this.started=now;this.phase=now-this.started<800?'startup':'running';if(this.phase==='startup'){const scale=Math.min(1,.08/Math.max(Math.abs(v),1e-9),.2/Math.max(Math.abs(w),1e-9));target=target.map(x=>x*scale);}let ratio=1;target.forEach((x,i)=>{const d=x-this.output[i];if(d)ratio=Math.min(ratio,(Math.abs(x)<Math.abs(this.output[i])?4:2)*dt/Math.abs(d));});this.output=this.output.map((x,i)=>x+(target[i]-x)*ratio);}
    this.wheels=this.wheels.map((x,i)=>Math.abs(this.output[i]-x)<.003?this.output[i]:x+(this.output[i]-x)*.33);this.position=this.position.map((x,i)=>x+this.wheels[i]*dt);
  }
  async state(){const motorAge=this.scene==='no_feedback'?null:(performance.now()-this.lastMotor)/1000;return {mode:'demo',ros_alive:true,driver:{state:this.fault?'fault':this.owner?this.phase:'ready',phase:this.phase,fault:this.fault,serial_connected:this.scene!=='serial',motor_feedback_fresh:motorAge!==null&&motorAge<=.5,motor_feedback_required:this.scene!=='no_feedback',lift_state:'disabled',lift_fault:''},motor:this.scene==='no_feedback'?null:[this.wheels[0],this.wheels[0]*12.75,this.position[0],this.wheels[1],this.wheels[1]*12.75,this.position[1]],applied:[(this.output[0]+this.output[1])*.06,(this.output[1]-this.output[0])*.12/.7],lift:null,ages:{motor:motorAge,driver:0,applied:0,lift:null},manual_allowed:!this.fault&&['normal','no_feedback'].includes(this.scene),blocked_reason:this.fault?'드라이버 정지 유지 / 오류를 먼저 복구하세요':'',controller:this.owner,services:{driver_stop:true,driver_reset:true,lift_set_home:false,lift_stop:false},publisher_count:1,topics:{cmd_vel:'/cmd_vel',motor_state:'/motor_state',cmd_vel_applied:'/cmd_vel_applied',driver_status:'/driver_status',lift_target:'/lift_target',lift_state:'/lift_state'},config:{wheel_radius:.12,wheel_separation:.7,lift_max_height:0},events:this.events,results:this.results};}
}

class LiveTransport {
  async init(){const r=await fetch('/api/session',{cache:'no-store',signal:AbortSignal.timeout(2000)});if(!r.ok)throw Error('로컬 ROS2 브리지에 연결할 수 없어요');const data=await r.json();if(data.mode!=='live'||!data.token)throw Error('브리지 응답을 확인하세요');this.token=data.token;}
  async post(path,body,keepalive=false){if(!this.token)throw Error('브리지가 연결되지 않았어요');const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Console-Token':this.token},body:JSON.stringify(body),keepalive,signal:AbortSignal.timeout(1500)});const data=await r.json();if(r.status===403){await this.init();throw Error('브리지 연결을 갱신했어요. 수동 제어 또는 요청을 다시 선택하세요.');}if(!r.ok)throw Error(data.error||'요청을 처리할 수 없어요');return data;}
  arm(){return this.post('arm',{client:CLIENT});}
  command(values,token,seq){return this.post('command',{epoch:token,seq,linear:values[0],angular:values[1]});}
  disarm(token){return this.post('disarm',{epoch:token},true);}
  service(name){return this.post('service',{name});}
  liftTarget(height){return this.post('lift-target',{height});}
  async state(){const r=await fetch('/api/state',{cache:'no-store',signal:AbortSignal.timeout(1200)});if(!r.ok)throw Error('피드백 연결을 확인하세요');return r.json();}
}

function clearHolds(){heldKeys.clear();heldPointers.clear();document.querySelectorAll('.drive-button').forEach(b=>b.classList.remove('pressed'));}
function paintHolds(){const all=new Set([...heldKeys,...heldPointers.values()]);document.querySelectorAll('[data-drive]').forEach(b=>b.classList.toggle('pressed',all.has(b.dataset.drive)));}
async function disarm(quiet=true){armGeneration++;const old=epoch;manual=false;epoch=null;clearHolds();renderControls();if(old){try{await transport.disarm(old);}catch(e){if(!quiet)toast('제어 해제 응답을 확인하지 못했어요. 조작 신호 만료 시 0속도를 보냅니다.',true);}}}
async function toggleManual(){if(manual){await disarm(false);return;}if(armBusy)return;armBusy=true;const generation=++armGeneration;renderControls();try{const data=await transport.arm();if(generation!==armGeneration||document.hidden){await transport.disarm(data.epoch);return;}epoch=data.epoch;manual=true;sequence=0;armedAt=performance.now();clearHolds();await sendCommand(true);toast('수동 제어를 켰어요. 방향 버튼을 누르고 있으면 움직여요.');}catch(e){toast(e.message,true);}finally{armBusy=false;renderControls();}}
async function sendCommand(force=false){if(!manual||!epoch||(!force&&commandBusy))return;const token=epoch,seq=++sequence,values=velocity();commandBusy=true;try{await transport.command(values,token,seq);}catch(e){if(token===epoch){await disarm();toast('조작 연결이 끊겨 수동 제어를 해제했어요.',true);}}finally{commandBusy=false;}}
async function callService(name){if(pendingServices.has(name))return;pendingServices.add(name);disarm();renderControls();try{const result=await transport.service(name);toast(name==='driver_stop'?'정지 유지 요청 전송 · 응답을 기다립니다.':'요청을 전송했어요.');if(result.job_id)setTimeout(()=>{pendingServices.delete(name);renderControls();},3500);}catch(e){toast(e.message,true);pendingServices.delete(name);}renderControls();}

function renderControls(){const online=!!snapshot&&performance.now()-lastHTTP<1300;const other=snapshot?.controller&&snapshot.controller!==CLIENT;const allowed=online&&snapshot.manual_allowed&&!other;
  $('manualToggle').setAttribute('aria-checked',String(manual));$('manualToggle').disabled=armBusy||(!manual&&!allowed);
  document.querySelectorAll('[data-drive]').forEach(b=>b.disabled=!manual);
  const notice=$('controlNotice');notice.classList.toggle('active',manual);notice.replaceChildren();const dot=document.createElement('span');dot.className=manual?'green-dot':'muted-dot';notice.append(dot,document.createTextNode(manual?'수동 제어 활성 · 놓으면 정지해요':other?'다른 브라우저에서 제어 중이에요':(!online?'연결 상태를 확인하고 있어요':snapshot?.blocked_reason||'수동 제어를 켜고 방향 버튼을 누르세요')));
  $('stopButton').disabled=!online||!snapshot.services?.driver_stop||pendingServices.has('driver_stop');$('headerStop').disabled=$('stopButton').disabled;$('resetButton').disabled=!online||!snapshot.services?.driver_reset||pendingServices.has('driver_reset');
}

function render(){if(!snapshot)return;const s=snapshot;const networkFresh=performance.now()-lastHTTP<1300;const motorFresh=networkFresh&&s.ages.motor!==null&&s.ages.motor<=.5;const driverFresh=networkFresh&&s.ages.driver!==null&&s.ages.driver<=1.2;
  if(manual&&((!s.manual_allowed)||(s.controller!==CLIENT&&performance.now()-armedAt>500))){disarm();}
  const m=motorFresh?s.motor:null;const radius=s.config.wheel_radius,sep=s.config.wheel_separation;
  const measured=m?[(m[0]+m[3])*radius/2,(m[3]-m[0])*radius/sep]:[NaN,NaN];
  $('linearValue').textContent=fmt(measured[0]);$('angularValue').textContent=fmt(measured[1]);$('feedbackAge').textContent=networkFresh&&finite(s.ages.motor)?String(Math.round(s.ages.motor*1000)):'—';
  $('leftWheel').innerHTML=fmt(m?.[0])+'<small>rad/s</small>';$('rightWheel').innerHTML=fmt(m?.[3])+'<small>rad/s</small>';
  $('leftPwm').textContent=fmt(m?.[1],1);$('rightPwm').textContent=fmt(m?.[4],1);$('leftPosition').textContent=fmt(m?.[2]);$('rightPosition').textContent=fmt(m?.[5]);
  $('leftDrive').classList.toggle('pulse-drive',!!m&&Math.abs(m[0])>.1);$('rightDrive').classList.toggle('pulse-drive',!!m&&Math.abs(m[3])>.1);
  const state=driverFresh&&s.driver?s.driver.state:'waiting_feedback';const error=!!s.driver?.fault;const withoutFeedback=driverFresh&&s.driver?.motor_feedback_required===false&&!motorFresh;const waiting=!networkFresh||!driverFresh||(!motorFresh&&!withoutFeedback);
  $('driverState').textContent=stateNames[state]||state;$('stateCode').textContent=state.toUpperCase();$('stateOrb').className='status-orb'+(error?' error':waiting?' waiting':'');
  $('serialState').textContent=!networkFresh?'연결 끊김':s.driver?.serial_connected?'시리얼 연결':'시리얼 대기';$('feedbackDot').style.background=motorFresh?'#6b9d6f':'#c8a269';$('footerDot').style.background=waiting?'#c8a269':error?'#c26054':'#6b9d6f';
  $('feedbackNote').textContent=motorFresh?'최근 모터 상태 기준':withoutFeedback?'피드백 없이 주행 허용':'피드백 미수신 / 만료';$('separationLabel').textContent=sep.toFixed(2)+' m';$('footerSeparation').textContent=sep.toFixed(2)+' m';$('liftPill').textContent=s.lift?'ON':'OFF';
  $('footerConnection').textContent=LOCAL?(networkFresh?'로컬 ROS2 브리지':'로컬 연결 끊김'):'데모 시뮬레이터';
  if(LOCAL){$('modeBanner').className='mode-banner '+(waiting||withoutFeedback?'warning':'live');$('modeTitle').textContent=waiting?'ROS 연결 확인 중':withoutFeedback?'실제 로봇 · 피드백 없이 주행':'실제 로봇 연결';$('modeDescription').textContent=waiting?(s.blocked_reason||'브리지와 피드백 상태를 확인하세요.'):withoutFeedback?'속도 명령을 보낼 수 있지만 실제 속도·정지는 확인할 수 없어요. 계측값은 —로 표시합니다.':'이 화면의 조작은 연결된 로봇에 명령을 전송합니다.';$('modeLink').textContent='연결 상태 보기';$('modeLink').dataset.dialog='connection';}else{$('modeBanner').className='mode-banner'+(withoutFeedback?' warning':'');$('modeTitle').textContent=withoutFeedback?'데모 · 피드백 없이 주행':'데모 모드';$('modeDescription').textContent=withoutFeedback?'피드백 없이 명령을 보내는 상황입니다. 실제 로봇에는 명령을 보내지 않고, 계측값은 —로 표시해요.':'가상 로봇으로 화면과 조작을 체험해보세요. 실제 로봇에는 명령을 보내지 않습니다.';}
  $('eventCount').textContent=s.events.length;renderEvents($('recentEvents'),s.events.slice(0,3));
  for(const result of s.results||[]){if(result.status!=='pending'&&!reportedResults.has(result.id+'-'+result.status)){reportedResults.add(result.id+'-'+result.status);pendingServices.delete(result.name);toast(result.message,result.status!=='success');}}
  renderControls();
  if(performance.now()-lastHistory>=180){lastHistory=performance.now();history.push({t:lastHistory,actual:finite(measured[0])?measured[0]:null,target:networkFresh&&s.ages.applied!==null&&s.ages.applied<=.6?s.applied?.[0]??null:null});history=history.filter(p=>lastHistory-p.t<61000);drawChart();}
  if(currentDialog==='topics')updateTopicValues();
  if(currentDialog==='logs')renderLogList();
  if(currentDialog==='lift')updateLiftValues();
}

function renderEvents(container,events){container.replaceChildren();if(!events.length){const empty=document.createElement('div');empty.className='empty-events';empty.textContent='아직 기록된 이벤트가 없어요.';container.append(empty);return;}
  for(const e of events){const row=document.createElement('div');row.className='event-row';row.innerHTML=`<span class="event-icon ${e.level==='error'?'error':''}">${icon(e.level==='error'?'info':'check')}</span><div class="event-copy"><strong>${esc(e.text)}</strong><small>${e.level==='error'?'상태 확인 필요':'시스템 이벤트'}</small></div><span class="event-time">${esc(eventTime(e))}</span>`;container.append(row);}}
function renderLogList(){const el=$('fullEvents');if(el)renderEvents(el,(snapshot?.events||[]).filter(e=>logFilter==='all'||e.level==='error'));}

function drawChart(){const c=$('speedChart'),rect=c.getBoundingClientRect();if(!rect.width||!rect.height)return;const ratio=window.devicePixelRatio||1;c.width=Math.round(rect.width*ratio);c.height=Math.round(rect.height*ratio);const ctx=c.getContext('2d');ctx.scale(ratio,ratio);const w=rect.width,h=rect.height,L=38,R=13,T=13,B=26,plotW=w-L-R,plotH=h-T-B;ctx.clearRect(0,0,w,h);ctx.font='9px Arial,sans-serif';ctx.lineWidth=1;ctx.textAlign='right';
  for(const val of [.3,.15,0,-.15,-.3]){const y=T+(.3-val)/.6*plotH;ctx.strokeStyle=val===0?'#dbe5d3':'#edf1e8';ctx.setLineDash(val===0?[]:[3,4]);ctx.beginPath();ctx.moveTo(L,y);ctx.lineTo(w-R,y);ctx.stroke();ctx.fillStyle='#a2b194';ctx.fillText(val.toFixed(2),L-8,y+3);}
  ctx.setLineDash([]);const now=performance.now();ctx.textAlign='center';for(let i=0;i<=4;i++){const x=L+plotW*i/4;ctx.fillStyle='#a2b194';ctx.fillText(i===4?'현재':`${Math.round(chartRange*(1-i/4))}초 전`,x,h-8);}
  function line(key,color,dash){ctx.strokeStyle=color;ctx.lineWidth=key==='actual'?1.9:1.4;ctx.setLineDash(dash);ctx.beginPath();let started=false;for(const p of history){if(p.t<now-chartRange*1000)continue;if(p[key]===null){started=false;continue;}const x=L+(p.t-(now-chartRange*1000))/(chartRange*1000)*plotW,y=T+(.3-Math.max(-.3,Math.min(.3,p[key])))/.6*plotH;if(!started){ctx.moveTo(x,y);started=true;}else ctx.lineTo(x,y);}ctx.stroke();}
  line('target','#acc391',[4,4]);line('actual','#438563',[]);
  if(history.length<3){ctx.fillStyle='#a8b79b';ctx.textAlign='center';ctx.fillText('속도 데이터를 기다리고 있어요',L+plotW/2,T+plotH/2-10);}}

function detailRow(label,value){return `<div class="detail-row"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`;}
function openDrawer(name){disarm();currentDialog=name;const title={connection:'연결 및 설정',guide:'실제 로봇 연결하기',logs:'이벤트 기록',topics:'ROS 인터페이스',lift:'리프트 제어'}[name];$('drawerTitle').textContent=title;const body=$('drawerBody');const s=snapshot;
  if(name==='connection'){body.innerHTML=`<p class="drawer-lead">${LOCAL?'같은 PC에서 실행 중인 ROS2 브리지에 연결합니다.':'현재 화면은 가상 데이터로 동작하는 데모입니다. 실제 운용은 로봇 PC에서 실행하세요.'}</p><div class="detail-card"><h3>현재 연결</h3>${detailRow('운용 모드',LOCAL?'실제 로봇 · 로컬':'데모 · 시뮬레이션')}${detailRow('연결 대상',LOCAL?location.origin:'브라우저 내 가상 로봇')}${detailRow('cmd_vel 발행기',s?.publisher_count===null?'확인 중':(s?.publisher_count??1)+'개')}${detailRow('좌우 구동륜 간격',(s?.config.wheel_separation??.7).toFixed(2)+' m')}${detailRow('구동륜 반지름',(s?.config.wheel_radius??.12).toFixed(2)+' m · 확인 필요')}</div><div class="detail-card"><h3>운용 설정</h3>${detailRow('수동 주행 상한','0.30 m/s')}${detailRow('수동 회전 상한','0.50 rad/s')}${detailRow('조작 신호 유효 시간','0.35초')}${detailRow('드라이버 명령 타임아웃','0.5초')}${detailRow('모터 피드백 필수',s?.driver?.motor_feedback_required===false?'아니요 · 미수신이어도 주행 허용':'예 · 피드백 정상일 때 주행')}</div>${!LOCAL?`<div class="detail-card"><h3>장애 상황 체험</h3><p>데모에서만 동작합니다. 정상으로 되돌린 후 복구 버튼을 누르세요.</p><select class="sim-select" id="simScene"><option value="normal">정상 연결</option><option value="no_feedback">피드백 없이 주행 허용</option><option value="feedback">피드백 필수 모드 · 중단 시 정지</option><option value="serial">시리얼 연결 끊김</option></select></div>`:''}<button class="button full-button" data-dialog="guide">${icon('link')} 실행 및 연결 가이드</button><div class="inline-note">수동 제어를 켜기 전 Nav2·teleop 등 다른 /cmd_vel 발행기를 종료하세요. 발행기 수 검사는 ROS 제어권 중재 기능을 대체하지 않습니다.</div>`;if($('simScene')){$('simScene').value=transport.scene;$('simScene').onchange=e=>transport.setScene(e.target.value);}}
  if(name==='guide'){body.innerHTML=`<p class="drawer-lead">드라이버와 관제 브리지를 로봇 PC에서 실행한 뒤, 같은 PC의 브라우저로 접속하세요. ROS2 Humble 환경 기준입니다.</p>${!LOCAL?`<a class="button full-button" href="https://github.com/kang-hyun/meta_cmd" target="_blank" rel="noopener noreferrer">${icon('download')} GitHub에서 실행 파일 받기</a>`:''}<div class="step-label">01 · 기존 드라이버 실행</div><div class="code-block" id="driverCode">source /opt/ros/humble/setup.bash
cd /path/to/meta_cmd
python3 mf_mobile_driver_node.py --ros-args \
  -p enable_lift:=false \
  -p wheel_separation:=0.70 \
  -p require_motor_feedback:=false</div><button class="code-copy" data-copy="driverCode">명령 복사</button><div class="step-label">02 · 새 터미널에서 관제 실행</div><div class="code-block" id="bridgeCode">source /opt/ros/humble/setup.bash
cd /path/to/meta_cmd
python3 ros_dashboard_bridge.py</div><button class="code-copy" data-copy="bridgeCode">명령 복사</button><div class="step-label">03 · 같은 PC의 브라우저에서 열기</div><div class="code-block" id="urlCode">http://127.0.0.1:8765</div><button class="code-copy" data-copy="urlCode">주소 복사</button><div class="inline-note">웹 미리보기에서 로봇에 직접 연결하지 않습니다. 받은 파일은 인터넷 없이 사용할 수 있고, 기본적으로 같은 PC에서만 접속됩니다. 드라이버와 브리지는 같은 저장소 버전을 사용하세요. 드라이버 기본 보드레이트는 921600이며 모터 피드백 없이도 주행을 허용합니다.</div><div class="detail-card"><h3>조작 방법</h3><p>시리얼과 드라이버 상태가 정상일 때 수동 제어를 켜세요. 모터 피드백이 없어도 수정 드라이버가 허용하면 조작할 수 있어요. 방향 버튼이나 키보드를 누르는 동안 명령을 보내고, 놓으면 0속도를 보냅니다.</p><div class="kbd-list"><span><kbd>W / ↑</kbd> 전진</span><span><kbd>S / ↓</kbd> 후진</span><span><kbd>A / ←</kbd> 제자리 좌회전</span><span><kbd>D / →</kbd> 제자리 우회전</span><span><kbd>Esc</kbd> 제어 해제</span><span><kbd>Space</kbd> 정지 유지</span></div></div><p class="drawer-lead">창 전환·탭 숨김·조작 신호 만료 시 수동 제어를 해제합니다. 정지 유지 후에는 바퀴가 멈춘 것을 확인하고 복구하세요. 피드백이 없으면 소프트웨어는 실제 정지를 확인할 수 없어요.</p>`;}
  if(name==='logs'){body.innerHTML=`<p class="drawer-lead">현재 세션의 연결·제어·오류 기록입니다. CSV로 저장할 수 있어요.</p><div class="log-filters"><div class="segmented"><button class="${logFilter==='all'?'selected':''}" data-log-filter="all">전체</button><button class="${logFilter==='error'?'selected':''}" data-log-filter="error">확인 필요</button></div><button class="button" id="exportLogs">${icon('download')} CSV 저장</button></div><div class="log-scroll" id="fullEvents"></div>`;renderLogList();$('exportLogs').onclick=exportLogs;}
  if(name==='topics'){const topics=[['cmd_vel','보내기 · geometry_msgs/msg/Twist','linear.x: 전후진 m/s · angular.z: 회전 rad/s. 수동 제어 중 주기 발행합니다.'],['motor_state','받기 · std_msgs/msg/Float64MultiArray','[왼쪽 속도, PWM, 누적 rad, 오른쪽 속도, PWM, 누적 rad]'],['cmd_vel_applied','받기 · geometry_msgs/msg/Twist','드라이버가 제한·출발 완화를 적용한 전송 목표. 실제 측정 속도가 아닙니다.'],['driver_status','받기 · std_msgs/msg/String','JSON 형식의 드라이버 상태와 장애 사유입니다.']];body.innerHTML=`<p class="drawer-lead">수정된 MF 드라이버의 ROS2 인터페이스입니다. 표시된 값은 ${LOCAL?'수신한 실제 데이터':'데모의 가상 데이터'}예요.</p>`+topics.map(([key,type,desc])=>`<details class="topic-item" ${key==='driver_status'?'open':''}><summary>${esc(s?.topics[key]||'/'+key)}</summary><p>${type}</p><p>${desc}</p><pre id="topic-${key}">—</pre></details>`).join('')+`<div class="detail-card"><h3>서비스 · std_srvs/srv/Trigger</h3>${detailRow('/driver_stop','정지 유지 요청')}${detailRow('/driver_reset','장애 해제 요청')}<p>요청은 {}, 응답은 success와 message입니다. 성공 응답이 물리적 정지를 보장하지는 않습니다.</p></div>`;updateTopicValues();}
  if(name==='lift'){if(!(s?.config.lift_max_height>0)){body.innerHTML=`<div class="disabled-lift">${icon('lift')}<h3>리프트가 비활성화되어 있어요</h3><p>현재 로봇은 주행 제어 모드입니다.<br>리프트 장착 시 설정과 피드백을 연결하세요.</p></div><div class="detail-card"><h3>활성화 조건</h3><p>드라이버의 enable_lift를 켜고 실제 허용 최대 높이 lift_max_height를 지정해야 합니다. 브리지에도 같은 높이를 --lift-max-height로 전달하세요.</p><p>HOME 완료, 센서 정상, 바퀴 정지 상태에서 높이 명령을 보낼 수 있습니다.</p></div>`;}else{body.innerHTML=`<p class="drawer-lead">바퀴가 정지한 상태에서만 조작할 수 있어요. HOME 응답은 요청 접수이며, 완료 여부는 피드백으로 확인합니다.</p><div class="detail-card"><h3>현재 높이</h3><div class="lift-value"><span id="liftHeight">—</span><small>m</small></div><div id="liftFlags"></div></div><div class="drawer-actions"><button class="button" data-service="lift_set_home">${icon('reset')} HOME</button><button class="button" data-service="lift_stop">${icon('stop')} 리프트 정지</button></div><div class="detail-card"><h3>목표 높이</h3><div class="lift-input"><input id="liftTarget" aria-label="리프트 목표 높이" type="number" min="0" max="${s.config.lift_max_height}" step="0.01" value="0"><span>m</span></div><p>허용 범위 0 ~ ${s.config.lift_max_height.toFixed(2)} m</p><button class="button full-button" id="sendLift">목표 높이 보내기</button></div>`;$('sendLift').onclick=async()=>{try{await transport.liftTarget(Number($('liftTarget').value));toast('목표 높이 요청을 전송했어요.');}catch(e){toast(e.message,true);}};updateLiftValues();}}
  if(!$('drawer').open)$('drawer').showModal();}

function updateTopicValues(){const s=snapshot;if(!s)return;const values={cmd_vel:{linear:{x:manual?velocity()[0]:0},angular:{z:manual?velocity()[1]:0}},motor_state:s.motor,cmd_vel_applied:s.applied,driver_status:s.driver};for(const [key,value]of Object.entries(values)){const el=$('topic-'+key);if(el)el.textContent=JSON.stringify(value,null,2)||'아직 수신하지 않았어요';}}
function updateLiftValues(){if(!$('liftHeight')||!snapshot)return;const s=snapshot,fresh=s.ages.lift!==null&&s.ages.lift<=.5;$('liftHeight').textContent=fresh?fmt(s.lift?.[0]):'—';const flags=fresh?Number(s.lift?.[2]):0;$('liftFlags').innerHTML=detailRow('센서 상태',fresh&&(flags&1)&&!(flags&8)?'정상':'확인 필요')+detailRow('HOME 상태',flags&16?'진행 중':flags&32?'완료':'미완료')+detailRow('드라이버 상태',s.driver?.lift_state||'대기');}
function exportLogs(){const csvCell=v=>{let str=String(v);if(/^[=+@-]/.test(str))str="'"+str;return '"'+str.replaceAll('"','""')+'"';};const rows=[['시간','구분','내용'],...(snapshot?.events||[]).map(e=>[new Date(e.time*1000).toISOString(),e.level,e.text])];const blob=new Blob(['\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mf_robot_events.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('이벤트 기록을 CSV로 저장했어요.');}

document.addEventListener('click',e=>{const dialogButton=e.target.closest('[data-dialog]');if(dialogButton){e.preventDefault();openDrawer(dialogButton.dataset.dialog);return;}const serviceButton=e.target.closest('[data-service]');if(serviceButton){callService(serviceButton.dataset.service);return;}const copy=e.target.closest('[data-copy]');if(copy){if(!navigator.clipboard){toast('텍스트를 직접 선택해 복사해주세요.');return;}navigator.clipboard.writeText($(copy.dataset.copy).textContent).then(()=>toast('복사했어요.')).catch(()=>toast('텍스트를 직접 선택해 복사해주세요.',true));return;}const filter=e.target.closest('[data-log-filter]');if(filter){logFilter=filter.dataset.logFilter;filter.parentNode.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===filter));renderLogList();return;}const range=e.target.closest('[data-range]');if(range){chartRange=Number(range.dataset.range);range.parentNode.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===range));drawChart();}if(e.target.closest('[data-action="dashboard"]')||e.target.closest('.brand')){e.preventDefault();window.scrollTo({top:0,behavior:'smooth'});}});
$('manualToggle').onclick=toggleManual;$('releaseButton').onclick=()=>{clearHolds();sendCommand(true);};$('stopButton').onclick=()=>callService('driver_stop');$('headerStop').onclick=()=>callService('driver_stop');$('resetButton').onclick=()=>callService('driver_reset');
$('closeDrawer').onclick=()=>{$('drawer').close();currentDialog='';};$('drawer').addEventListener('close',()=>{currentDialog='';});$('drawer').addEventListener('click',e=>{if(e.target===$('drawer')&&e.clientX<$('drawer').getBoundingClientRect().left){$('drawer').close();}});
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('이 브라우저에서는 전체 화면 전환을 사용할 수 없어요.');}};
for(const id of ['linearSlider','angularSlider']){$(id).addEventListener('input',()=>{linearSetting=Number($('linearSlider').value);angularSetting=Number($('angularSlider').value);$('linearSetting').innerHTML=linearSetting.toFixed(2)+' <small>m/s</small>';$('angularSetting').innerHTML=angularSetting.toFixed(2)+' <small>rad/s</small>';for(const input of [$('linearSlider'),$('angularSlider')]){const pct=(Number(input.value)-Number(input.min))/(Number(input.max)-Number(input.min))*100;input.style.background=`linear-gradient(to right,#608751 ${pct}%,#e7ede1 ${pct}%)`;}if(manual)sendCommand(true);});}
document.querySelectorAll('[data-drive]').forEach(button=>{button.addEventListener('pointerdown',e=>{if(!manual||button.disabled||e.button!==0)return;e.preventDefault();button.setPointerCapture(e.pointerId);heldPointers.set(e.pointerId,button.dataset.drive);paintHolds();sendCommand(true);});const release=e=>{if(heldPointers.delete(e.pointerId)){paintHolds();sendCommand(true);}};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release);});
const keyMap={KeyW:'forward',ArrowUp:'forward',KeyS:'backward',ArrowDown:'backward',KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right'};
window.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.code==='Escape'){disarm();return;}if(e.code==='Space'&&!$('drawer').open){e.preventDefault();if(!e.repeat)callService('driver_stop');return;}if(!manual||!keyMap[e.code]||$('drawer').open)return;e.preventDefault();if(e.repeat)return;heldKeys.add(keyMap[e.code]);paintHolds();sendCommand(true);});
window.addEventListener('keyup',e=>{if(keyMap[e.code]&&heldKeys.delete(keyMap[e.code])){paintHolds();sendCommand(true);}});
window.addEventListener('blur',()=>disarm());document.addEventListener('visibilitychange',()=>{if(document.hidden)disarm();});window.addEventListener('pagehide',()=>disarm());window.addEventListener('resize',drawChart);
new ResizeObserver(drawChart).observe($('speedChart'));
setInterval(()=>{$('clock').textContent=new Date().toLocaleTimeString('ko-KR',{hour12:false});if(manual)sendCommand();if(snapshot&&performance.now()-lastHTTP>1300){if(manual)disarm();renderControls();}},100);

async function poll(){try{snapshot=await transport.state();lastHTTP=performance.now();render();}catch(e){if(manual)await disarm();$('modeBanner').className='mode-banner warning';$('modeTitle').textContent='브리지 연결 확인';$('modeDescription').textContent='관제 브리지가 실행 중인지 확인하세요. 연결이 돌아와도 자동으로 제어를 켜지 않습니다.';renderControls();if(snapshot){snapshot.ages={motor:null,driver:null,applied:null,lift:null};render();}else{$('linearValue').textContent=$('angularValue').textContent='—';$('driverState').textContent='연결 대기';$('stateCode').textContent='OFFLINE';}}
  setTimeout(poll,200);}
async function boot(){transport=LOCAL?new LiveTransport():new DemoTransport();if(LOCAL){$('modeTitle').textContent='실제 로봇 · 연결 대기';$('modeDescription').textContent='같은 PC의 ROS2 브리지를 확인하고 있어요.';$('linearValue').textContent=$('angularValue').textContent='—';}renderControls();try{await transport.init();}catch(e){toast(e.message,true);if(LOCAL){setTimeout(boot,2500);return;}}poll();}
boot();
